import importlib.util, os
spec = importlib.util.spec_from_file_location("lib", os.path.join(os.path.dirname(__file__), "es-stories-lib.py"))
lib = importlib.util.module_from_spec(spec); spec.loader.exec_module(lib)
story = lib.story

S = []
S.append(story("la_musica_de_al_lado", "A2-1", "La música de al lado",
 ("Đêm nào chàng trai nhà bên cũng chơi nhạc đến hai giờ sáng. Laura quyết định sang nói chuyện.", "Every night the young man next door plays music until two in the morning. Laura decides to go and talk to him."),
 ["piso", "molestar", "soler", "mantener", "formar"],
 [("N", "Laura vive sola en un piso pequeño del centro de Bilbao.", "Laura sống một mình trong một căn hộ nhỏ ở trung tâm Bilbao.", "Laura lives alone in a small flat in the centre of Bilbao."),
  ("N", "Trabaja en un hospital y suele acostarse a las once, porque empieza muy temprano.", "Cô làm ở bệnh viện và thường đi ngủ lúc mười một giờ, vì cô bắt đầu làm việc từ rất sớm.", "She works in a hospital and usually goes to bed at eleven, because she starts very early."),
  ("N", "Pero desde hace una semana, alguien toca música en el piso de al lado hasta las dos de la mañana.", "Nhưng từ một tuần nay, có người chơi nhạc ở căn hộ bên cạnh đến tận hai giờ sáng.", "But for a week now, someone in the flat next door has been playing music until two in the morning."),
  ("N", "Laura no puede dormir, y llega al trabajo muy cansada.", "Laura không ngủ được, và đến chỗ làm trong tình trạng mệt rã rời.", "Laura can't sleep, and she arrives at work exhausted."),
  ("N", "El jueves por la noche decide hablar con el chico de al lado.", "Tối thứ Năm, cô quyết định sang nói chuyện với cậu thanh niên nhà bên.", "On Thursday night she decides to talk to the young man next door."),
  ("N", "Llama a la puerta, y abre un chico muy joven.", "Cô gõ cửa, và một chàng trai rất trẻ ra mở.", "She knocks, and a very young man opens the door."),
  ("B", "Hola. ¿Qué sucede?", "Chào chị. Có chuyện gì vậy?", "Hi. What's up?"),
  ("A", "Hola. Perdona que te moleste, pero tu música me molesta a mí. Son más de las doce.", "Chào cậu. Xin lỗi đã làm phiền, nhưng tiếng nhạc của cậu đang làm phiền tôi đấy. Đã quá mười hai giờ đêm rồi.", "Hi. Sorry to bother you, but your music is bothering me. It's past midnight."),
  ("B", "¡Ay, lo siento mucho! No sabía que se oía tanto.", "Ôi, em xin lỗi chị nhiều! Em không biết là nghe rõ đến thế.", "Oh, I'm so sorry! I didn't know you could hear it so much."),
  ("N", "El chico se llama Bruno. Es de Sevilla y llegó a Bilbao hace poco.", "Chàng trai tên là Bruno. Cậu người Sevilla và mới đến Bilbao chưa lâu.", "The young man is called Bruno. He's from Seville and came to Bilbao not long ago."),
  ("B", "Quiero formar una banda aquí, y toco cada noche para no olvidar las canciones.", "Em muốn lập một ban nhạc ở đây, nên đêm nào em cũng chơi để không quên các bài.", "I want to form a band here, and I play every night so I don't forget the songs."),
  ("A", "Muy bien, pero yo entro a trabajar a las siete de la mañana.", "Hay đấy, nhưng bảy giờ sáng tôi đã phải vào ca rồi.", "That's great, but I start work at seven in the morning."),
  ("B", "Tienes razón. Tenemos que mantener la paz.", "Chị nói đúng. Hàng xóm mình phải giữ hòa khí với nhau.", "You're right. We have to keep the peace."),
  ("N", "Así que buscan una forma de vivir bien los dos: Bruno va a tocar solo hasta las diez.", "Thế là hai người tìm ra một cách để cả hai cùng sống thoải mái: Bruno sẽ chỉ chơi đến mười giờ.", "So they find a way for both of them to live well: Bruno will only play until ten."),
  ("N", "Laura ve muchos papeles con música encima de la mesa.", "Laura thấy rất nhiều tờ giấy chép nhạc trên bàn.", "Laura sees lots of sheets of music on the table."),
  ("A", "¿Esas canciones son tuyas?", "Mấy bài hát này là của cậu à?", "Are those songs yours?"),
  ("B", "Sí. Las escribo yo. ¿Quieres oír una? Pero solo una, ¿vale?", "Vâng. Em tự viết đấy. Chị muốn nghe thử một bài không? Nhưng chỉ một bài thôi nhé?", "Yes. I write them myself. Do you want to hear one? But just one, all right?"),
  ("N", "Bruno toca una canción. Es tan hermosa que Laura se olvida del sueño.", "Bruno chơi một bài. Bài hát hay đến mức Laura quên cả buồn ngủ.", "Bruno plays a song. It's so beautiful that Laura forgets how sleepy she is."),
  ("N", "Incluso le pide otra.", "Cô còn xin cậu chơi thêm một bài nữa.", "She even asks for another one."),
  ("N", "Un mes después, Bruno toca con su banda nueva en un bar del centro.", "Một tháng sau, Bruno biểu diễn cùng ban nhạc mới ở một quán bar trong trung tâm.", "A month later, Bruno plays with his new band in a bar in the centre."),
  ("N", "Laura está allí, delante de todos. Esa noche no le importa acostarse tarde.", "Laura có mặt ở đó, đứng ngay hàng đầu. Đêm ấy, cô chẳng ngại đi ngủ muộn.", "Laura is there, right at the front. That night she doesn't mind going to bed late.")],
 [("locate", "Laura thường đi ngủ lúc mấy giờ?", "What time does Laura usually go to bed?", [("Lúc mười giờ", "At ten"), ("Lúc mười một giờ", "At eleven"), ("Lúc hai giờ sáng", "At two in the morning")], 1),
  ("locate", "Hai người thống nhất điều gì?", "What do they agree on?", [("Bruno sẽ chuyển nhà", "Bruno will move out"), ("Laura sẽ đi ngủ muộn hơn", "Laura will go to bed later"), ("Bruno chỉ chơi nhạc đến mười giờ", "Bruno will only play until ten")], 2),
  ("infer", "Vì sao cuối truyện Laura không ngại đi ngủ muộn?", "Why doesn't Laura mind going to bed late at the end?", [("Vì hôm sau cô không phải đi làm", "Because she doesn't work the next day"), ("Vì cô muốn nghe ban nhạc của Bruno, người cô giờ đã quý mến", "Because she wants to hear the band of Bruno, whom she now likes"), ("Vì nhạc ở quán bar rất nhỏ", "Because the music in the bar is very quiet")], 1)],
 names=["Laura", "Bilbao", "Bruno", "Sevilla"],
 token_map={"acostarse": "es:w:acostar", "siento": "es:w:sentir"}))

S.append(story("la_entrevista_de_carla", "A2-1", "La entrevista de Carla",
 ("Carla có buổi phỏng vấn xin việc ở một khách sạn lớn. Trên đường đi, cô dừng lại giúp một ông cụ.", "Carla has a job interview at a big hotel. On the way, she stops to help an old man."),
 ["obtener", "vestir", "suceder", "camisa", "pantalon"],
 [("N", "Carla tiene 24 años y busca trabajo desde hace seis meses.", "Carla 24 tuổi và đã tìm việc được sáu tháng.", "Carla is 24 and has been looking for work for six months."),
  ("N", "Hoy tiene una reunión muy importante en el mejor hotel de Málaga: quieren una persona para trabajar con los clientes.", "Hôm nay cô có một cuộc gặp rất quan trọng ở khách sạn tốt nhất Málaga: họ cần người làm việc với khách.", "Today she has a very important meeting at the best hotel in Málaga: they want someone to work with the guests."),
  ("N", "Por la mañana no sabe cómo vestirse. Se pone una camisa blanca y un pantalón negro.", "Buổi sáng, cô không biết nên mặc gì. Cô chọn một chiếc áo sơ mi trắng và một chiếc quần đen.", "In the morning she doesn't know what to wear. She puts on a white shirt and black trousers."),
  ("A", "Mamá, ¿qué tal estoy?", "Mẹ ơi, con trông thế nào?", "Mum, how do I look?"),
  ("N", "Su madre le dice que está perfecta y que no tiene que tener miedo.", "Mẹ bảo cô trông rất ổn và không việc gì phải sợ.", "Her mother tells her she looks perfect and that there's no need to be scared."),
  ("N", "Carla sale de casa temprano. No suele llegar tarde, pero hoy no quiere tener ningún problema.", "Carla ra khỏi nhà từ sớm. Cô ít khi đến muộn, nhưng hôm nay cô không muốn có bất kỳ trục trặc nào.", "Carla leaves home early. She doesn't usually arrive late, but today she doesn't want any problems."),
  ("N", "En la calle, cerca del hotel, ve a un señor de unos 70 años que no puede levantarse. Sus papeles están por toda la calle.", "Trên phố, gần khách sạn, cô thấy một ông cụ chừng 70 tuổi bị ngã không đứng dậy được. Giấy tờ của ông vương vãi khắp mặt đường.", "In the street, near the hotel, she sees a man of about 70 who can't get up. His papers are all over the street."),
  ("A", "¿Qué le sucede, señor? ¿Está bien?", "Ông bị sao vậy ạ? Ông có sao không?", "What's wrong, sir? Are you all right?"),
  ("B", "Sí, sí, gracias. No es nada. Solo estoy un poco cansado.", "Có, có, cảm ơn cháu. Không sao đâu. Ông chỉ hơi mệt thôi.", "Yes, yes, thank you. It's nothing. I'm just a bit tired."),
  ("N", "Carla lo ayuda a levantarse y recoge todos sus papeles.", "Carla đỡ ông dậy và nhặt hết giấy tờ cho ông.", "Carla helps him up and picks up all his papers."),
  ("N", "Después lo lleva a un bar y le pide un café y agua.", "Rồi cô dìu ông vào một quán bar, gọi cho ông một tách cà phê và nước.", "Then she takes him to a bar and orders him a coffee and some water."),
  ("N", "Cuando mira la hora, son las diez y cinco. ¡La reunión era a las diez!", "Khi nhìn đồng hồ thì đã mười giờ năm phút. Cuộc gặp là lúc mười giờ!", "When she checks the time, it's five past ten. The meeting was at ten!"),
  ("N", "Carla corre al hotel. Allí, una chica le dice que espere un momento.", "Carla chạy vội đến khách sạn. Ở đó, một cô gái bảo cô chờ một lát.", "Carla runs to the hotel. There, a young woman tells her to wait a moment."),
  ("N", "Después de unos minutos se abre una puerta, y entra… ¡el señor de la calle!", "Vài phút sau, một cánh cửa mở ra, và người bước vào là… ông cụ ngoài phố!", "After a few minutes a door opens, and in comes… the man from the street!"),
  ("B", "Buenos días otra vez. Soy el jefe de este hotel. Siéntese, por favor.", "Chào cháu lần nữa. Ông là người quản lý khách sạn này. Cháu ngồi đi.", "Good morning again. I'm the manager of this hotel. Please sit down."),
  ("N", "Carla no sabe qué decir. El señor se ríe.", "Carla không biết phải nói gì. Ông cụ bật cười.", "Carla doesn't know what to say. The man laughs."),
  ("B", "En este hotel buscamos personas que sepan ayudar a otras personas. Y usted eso ya lo sabe hacer.", "Ở khách sạn này, chúng tôi tìm những người biết giúp đỡ người khác. Và điều đó thì cháu đã biết làm rồi.", "At this hotel we look for people who know how to help others. And you already know how to do that."),
  ("N", "Le hace unas preguntas más, sobre los idiomas y sus trabajos de antes, y Carla responde sin miedo.", "Ông hỏi thêm vài câu về ngoại ngữ và những công việc trước đây, và Carla trả lời không chút sợ sệt.", "He asks her a few more questions, about languages and her previous jobs, and Carla answers without fear."),
  ("N", "Una semana después, Carla obtiene el trabajo.", "Một tuần sau, Carla nhận được công việc.", "A week later, Carla gets the job."),
  ("N", "Y desde ese día, cada mañana, le prepara un café a su jefe.", "Và từ hôm đó, sáng nào cô cũng pha một tách cà phê cho sếp của mình.", "And since that day, every morning, she makes her boss a coffee.")],
 [("locate", "Carla mặc gì đi phỏng vấn?", "What does Carla wear to the interview?", [("Áo sơ mi trắng và quần đen", "A white shirt and black trousers"), ("Một chiếc váy đỏ", "A red dress"), ("Áo khoác đen", "A black jacket")], 0),
  ("locate", "Ông cụ ngoài phố thật ra là ai?", "Who is the man from the street, really?", [("Bố của Carla", "Carla's father"), ("Người quản lý khách sạn", "The hotel manager"), ("Một vị khách", "A guest")], 1),
  ("infer", "Vì sao Carla được nhận vào làm dù đến muộn?", "Why does Carla get the job even though she was late?", [("Vì cô nói nhiều ngoại ngữ", "Because she speaks many languages"), ("Vì mẹ cô quen ông quản lý", "Because her mother knows the manager"), ("Vì cô đã giúp ông cụ, và khách sạn cần người biết giúp đỡ người khác", "Because she helped the old man, and the hotel wants people who help others")], 2)],
 names=["Carla", "Málaga"],
 token_map={"vestirse": "es:w:vestir", "levantarse": "es:w:levantar", "siéntese": "es:w:sentar", "espere": "es:w:esperar"}))

S.append(story("el_pho_de_linh", "A2-1", "El pho de Linh",
 ("Linh mời cả lớp tiếng Tây Ban Nha đến nhà ăn phở. Thầy Andrés muốn học nấu.", "Linh invites her Spanish class home for pho. Andrés, the teacher, wants to learn to cook it."),
 ["probar", "echar", "carne", "cocinar"],
 [("N", "Linh lleva seis meses en la escuela de idiomas y ya habla bastante bien.", "Linh học ở trường ngoại ngữ được sáu tháng và giờ đã nói khá giỏi.", "Linh has been at the language school for six months and already speaks quite well."),
  ("N", "Un día, el profesor Andrés le pregunta qué comen en Vietnam por la mañana.", "Một hôm, thầy Andrés hỏi cô người Việt Nam ăn gì vào buổi sáng.", "One day, Andrés, the teacher, asks her what people eat in Vietnam in the morning."),
  ("A", "Muchas personas comen pho: una sopa con carne y arroz.", "Nhiều người ăn phở: một món súp có thịt và bánh làm từ gạo.", "Lots of people eat pho: a soup with meat and rice noodles."),
  ("B", "¿Sopa por la mañana? ¡Qué diferente!", "Ăn súp vào buổi sáng á? Khác quá nhỉ!", "Soup in the morning? How different!"),
  ("A", "¿Por qué no venís a mi casa el domingo? Os preparo un pho.", "Sao cả lớp không đến nhà em vào Chủ nhật? Em nấu phở cho mọi người ăn.", "Why don't you all come to my place on Sunday? I'll make you some pho."),
  ("N", "El domingo, todo el grupo está en casa de Linh a las doce.", "Chủ nhật, cả nhóm có mặt ở nhà Linh lúc mười hai giờ.", "On Sunday, the whole group is at Linh's place at twelve."),
  ("N", "Linh empezó a cocinar la sopa a las seis de la mañana. El pho necesita muchas horas.", "Linh đã bắt đầu nấu nồi nước dùng từ sáu giờ sáng. Phở cần ninh rất nhiều giờ.", "Linh started cooking the soup at six in the morning. Pho needs many hours."),
  ("B", "Yo también quiero aprender. ¿Me enseñas?", "Thầy cũng muốn học. Em dạy thầy nhé?", "I want to learn too. Will you teach me?"),
  ("N", "Linh le explica cómo cortar la carne en partes muy pequeñas y cómo echar la sopa encima.", "Linh chỉ cho thầy cách thái thịt thật nhỏ và cách chan nước dùng lên trên.", "Linh shows him how to cut the meat into very small pieces and how to pour the soup over it."),
  ("N", "Andrés lo intenta, pero corta la carne en partes muy grandes. Todos se ríen.", "Thầy Andrés thử làm, nhưng thái ra những miếng to tướng. Ai cũng bật cười.", "Andrés tries, but he cuts the meat into very big pieces. Everyone laughs."),
  ("A", "No pasa nada. Así es tu pho, el pho de Andrés.", "Không sao đâu ạ. Thế là phở của thầy, phở kiểu Andrés.", "Never mind. That's his pho, Andrés's pho."),
  ("N", "Después, todos se sientan a la mesa y prueban la sopa.", "Sau đó, mọi người ngồi vào bàn và nếm thử bát phở.", "Then everyone sits down at the table and tries the soup."),
  ("N", "Al señor de Alemania le encanta. Incluso pide más.", "Ông người Đức thích mê. Ông còn xin thêm nữa.", "The man from Germany loves it. He even asks for more."),
  ("N", "Marco dice que en Italia también hay sopas, pero ninguna como esta.", "Marco bảo ở Ý cũng có các món súp, nhưng chẳng món nào giống món này.", "Marco says there are soups in Italy too, but none like this one."),
  ("B", "Linh, ¿cómo se dice «muy bueno» en vietnamita?", "Linh ơi, «rất ngon» tiếng Việt nói thế nào?", "Linh, how do you say 'really good' in Vietnamese?"),
  ("A", "Se dice «ngon». Pero hoy, aquí, es el profesor el que aprende.", "Nói là «ngon» ạ. Nhưng hôm nay, ở đây, người học lại là thầy đấy.", "You say 'ngon'. But today, here, it's the teacher who is learning."),
  ("N", "Todos dicen la palabra: «ngon, ngon». Algunos la dicen muy mal, y Linh se ríe.", "Mọi người đồng thanh nhắc lại: «ngon, ngon». Có người nói sai bét, và Linh bật cười.", "They all repeat the word: 'ngon, ngon'. Some say it very badly, and Linh laughs."),
  ("N", "Esa noche, Linh llama a su madre en Hanói y le cuenta todo, en vietnamita y un poco en español.", "Tối hôm đó, Linh gọi cho mẹ ở Hà Nội và kể hết mọi chuyện, bằng tiếng Việt xen một chút tiếng Tây Ban Nha.", "That night Linh calls her mother in Hanoi and tells her everything, in Vietnamese and a little Spanish."),
  ("N", "Su madre se ríe cuando oye a su hija decir «vale» cada dos palabras.", "Mẹ cô bật cười khi nghe con gái cứ hai chữ lại nói «vale» một lần.", "Her mother laughs when she hears her daughter say 'vale' every other word.")],
 [("locate", "Linh bắt đầu nấu nồi nước dùng từ mấy giờ?", "What time did Linh start cooking the soup?", [("Mười hai giờ", "Twelve o'clock"), ("Sáu giờ sáng", "Six in the morning"), ("Tối hôm trước", "The evening before")], 1),
  ("locate", "Thầy Andrés thái thịt thế nào?", "How does Andrés cut the meat?", [("Thành những miếng to tướng", "Into huge pieces"), ("Thật mỏng, như Linh", "Very thin, like Linh"), ("Thầy không thái", "He doesn't cut it")], 0),
  ("infer", "Linh muốn nói gì khi bảo «hôm nay người học lại là thầy»?", "What does Linh mean when she says 'today it's the teacher who is learning'?", [("Rằng thầy Andrés không biết tiếng Tây Ban Nha", "That Andrés doesn't know Spanish"), ("Rằng hôm nay thầy học từ cô: nấu phở và nói tiếng Việt", "That today he is learning from her: cooking pho and speaking Vietnamese"), ("Rằng lớp học bị hủy", "That the class is cancelled")], 1)],
 names=["Linh", "Andrés", "Vietnam", "Alemania", "Marco", "Italia", "Hanói", "pho", "ngon"],
 token_map={"como": "function", "venís": "es:w:venir", "cuenta": "es:w:contar"}))

lib.write_batch("06", S)
